<?php
function su_assert($v,$message='Assertion failed'){if(!$v)throw new RuntimeException($message);}
function su_case($name,$fn){global $tests,$failures;$tests++;try{$fn();echo 'PASS '.$name."\n";}catch(Throwable $e){$failures++;echo 'FAIL '.$name.': '.$e->getMessage()."\n";}}
function su_reject($fn,$expected){try{$fn();}catch(Throwable $e){su_assert($e->getMessage()===$expected||$e->getCode()===$expected,'Unexpected safe failure: '.get_class($e));return;}throw new RuntimeException('Expected rejection');}
function su_http($user,$path,$payload=null){$old=get_current_user_id();$cookies=$_COOKIE;try{wp_set_current_user($user);$token=WP_Session_Tokens::get_instance($user)->create(time()+3600);$jar=array();foreach(array(LOGGED_IN_COOKIE=>'logged_in',AUTH_COOKIE=>'auth')as $name=>$scheme){$value=wp_generate_auth_cookie($user,time()+3600,$scheme,$token);$_COOKIE[$name]=$value;$jar[]=new WP_Http_Cookie(array('name'=>$name,'value'=>$value));}if(is_array($payload)&&!isset($payload['_wpnonce']))$payload['_wpnonce']=wp_create_nonce('eipsi_setup_keys');if(is_array($payload)&&($payload['action']??null)==='eipsi_disable_external_db'&&!isset($payload['nonce']))$payload['nonce']=wp_create_nonce('eipsi_admin_nonce');$r=wp_remote_request('http://127.0.0.1'.$path,array('method'=>$payload===null?'GET':'POST','body'=>$payload,'cookies'=>$jar,'redirection'=>0,'timeout'=>30,'headers'=>array('Host'=>'127.0.0.1:18080')));su_assert(!is_wp_error($r));wp_cache_flush();return array('status'=>wp_remote_retrieve_response_code($r),'body'=>wp_remote_retrieve_body($r),'location'=>wp_remote_retrieve_header($r,'location'));}finally{$_COOKIE=$cookies;wp_set_current_user($old);}}
function su_mode($mode){update_option('eipsi_setup_fixture_mode',$mode,false);wp_cache_delete('alloptions','options');}
